def transform(grid):
    a=[r[:] for r in grid]
    h,w=len(a),len(a[0])
    for r in range(h):
        if r<2:
            for c in range(w):
                if a[r][c]==0: a[r][c]=1
            continue
        for c in range(min(3,w)):
            if a[r][c]==0: a[r][c]=1 if c<2 else 4
        # The colored field repeats every five cells. Infer each phase from
        # the most reliable right-hand uninterrupted section of the row.
        vals={}
        for c in range(w-1,2,-1):
            v=a[r][c]
            if v:
                vals[c%5]=v
        for c in range(3,w):
            if a[r][c]==0 and c%5 in vals: a[r][c]=vals[c%5]
    return a
